def seed_categories(apps, schema_editor):  # type: ignore[no-untyped-def]
    """Default categories for existing spaces; wedding expenses so far were vendor costs."""
    Organization = apps.get_model("organizations", "Organization")
    ExpenseCategory = apps.get_model("finance", "ExpenseCategory")
    Expense = apps.get_model("finance", "Expense")
    schema_editor.execute("SET LOCAL app.bypass_rls = 'on'")
    for organization in Organization.objects.all():
        categories = {
            name: ExpenseCategory.objects.get_or_create(
                organization=organization, name=name, defaults={"position": position}
            )[0]
            for position, name in enumerate(DEFAULTS)
        }
        Expense._base_manager.filter(organization=organization, category__isnull=True).update(
            category=categories["Sous-traitance"]
        )


